{{ config(
            materialized='table',
                post_hook={
                    "sql": "Create OR REPLACE table rpsg_db.maplemonk.Dr_Level_Details as WITH doctor_appointments AS ( SELECT d.DOCTORID AS doctor_id, d.\"Doctor Name\", a.ID AS appointment_id, a.DOCTORID AS appointment_doctor_id FROM RPSG_DB.MAPLEMONK.DRNAME_CONSULTATIONS d JOIN rpsg_db.maplemonk.pg_three60you_appointment a ON d.DOCTORID = a.DOCTORID ), invoicedatemetrics AS ( SELECT try_to_date(FI.invoice_date) AS Invoice_Date, sum(case when FI.rr_flag is null and lower(FI.order_status) not in (\'cancelled\') then ifnull(FI.selling_price, 0) - ifnull(FI.tax, 0) end) AS wo_rr_Realised_Revenue, sum(ifnull(case when lower(FI.order_status) not in (\'cancelled\') then ifnull(FI.selling_price, 0) - ifnull(FI.tax, 0) end, 0)) AS Realised_Revenue, DA.\"Doctor Name\" -- Reference Doctor Name with alias DA FROM RPSG_DB.MAPLEMONK.SALES_CONSOLIDATED_THREE60 FI LEFT JOIN doctor_appointments DA ON FI.appointment_id = DA.appointment_id WHERE NOT(lower(FI.order_status) IN (\'cancelled\')) AND FI.invoice_date != \'\' AND lower(FI.SHOP_NAME) = \'consultations\' GROUP BY try_to_date(FI.invoice_date), DA.\"Doctor Name\" ORDER BY try_to_date(FI.invoice_date) DESC ), returnsales AS ( SELECT return_date::date AS return_date, count(distinct case when FI.rr_flag is null then FI.reference_code end) AS wo_rr_return_orders_count, sum(case when FI.rr_flag is null then ifnull(total_return_amount_excl_tax, 0) end) AS wo_rr_TOTAL_RETURN_AMOUNT_EXCL_TAX, count(distinct FI.reference_code) AS return_orders_count, sum(total_return_amount) AS TOTAL_RETURN_AMOUNT, sum(total_return_amount_excl_tax) AS TOTAL_RETURN_AMOUNT_EXCL_TAX, sum(total_returned_quantity) AS TOTAL_RETURNED_QUANTITY, DA.\"Doctor Name\" -- Reference Doctor Name with alias IM FROM RPSG_DB.MAPLEMONK.easyecom_returns_summary_three60 FI left join RPSG_DB.MAPLEMONK.SALES_CONSOLIDATED_THREE60 a on FI.reference_code = a.ORDER_ID LEFT JOIN doctor_appointments DA ON a.appointment_id = DA.appointment_id WHERE lower(FI.SHOP_NAME) = \'consultations\' GROUP BY return_date, DA.\"Doctor Name\" ORDER BY return_date DESC ), orders AS ( SELECT FI.order_date::date AS Date, count(distinct FI.appointment_id) AS total_consultations, sum(ifnull(FI.selling_price, 0)) - sum(ifnull(FI.tax, 0)) AS Total_Sales_Ex_Tax, ifnull(sum(case when FI.return_flag = 1 then FI.suborder_quantity end), 0) AS Return_Quantity, ifnull(sum(case when FI.return_flag = 1 then ifnull(FI.SELLING_PRICE, 0) end), 0) AS Return_Value, count(distinct case when FI.return_flag = 1 then FI.order_id end) AS Return_Orders, count(distinct case when lower(FI.final_status) in (\'cancelled\') then FI.order_id end) AS Cancelled_Orders, count(distinct case when lower(FI.order_status) not in (\'cancelled\') and FI.return_flag = 0 then FI.order_id end) AS Net_Orders, count(distinct case when lower(FI.final_status) in (\'delivered\') then FI.order_id end) AS Delivered_Orders, count(distinct case when lower(FI.final_status) in (\'returned\', \'rto\') then FI.order_id end) AS Returned_Orders, sum(case when lower(FI.final_status) in (\'delivered\') then ifnull(FI.SELLING_PRICE, 0) - ifnull(FI.TAX, 0) end) AS Delivered_Revenue, sum(case when lower(FI.final_status) in (\'returned\', \'rto\') then ifnull(FI.SELLING_PRICE, 0) - ifnull(FI.TAX, 0) end) AS Returned_Revenue, DA.\"Doctor Name\" -- Reference Doctor Name with alias DA FROM RPSG_DB.MAPLEMONK.SALES_CONSOLIDATED_THREE60 FI LEFT JOIN doctor_appointments DA ON FI.appointment_id = DA.appointment_id WHERE lower(FI.SHOP_NAME) = \'consultations\' GROUP BY FI.order_date::date, DA.\"Doctor Name\" ), consultations1 AS ( SELECT CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\', start_timestamp :: DATETIME) ::date AS start_date, \'CONSULTATIONS\' AS c_marketplace, \'three60\' as data_source, null as c_channel, count(distinct case when LOWER(status) = \'completed\' then id end) as consultation_completed, count(distinct id ) as consultation_confirmed, \"Doctor Name\" FROM ( select * from ( select a.*, case when LOWER(status) = \'completed\' then 1 else 2 end as df, right(regexp_replace(c.phone, \'[^a-zA-Z0-9]+\'),10) phone, row_number() over(partition by end_timestamp::date,phone order by df asc ) rw, d.\"Doctor Name\" -- Include Doctor Name from rpsg_db.maplemonk.pg_three60you_appointment a left join rpsg_db.maplemonk.pg_three60you_customer c on lower(c.id) = lower(a.customer_id) left join rpsg_db.maplemonk.drname_consultations d on a.DOCTORID = d.DOCTORID where right(regexp_replace(phone, \'[^a-zA-Z0-9]+\'),10) not in (select distinct right(regexp_replace(phone, \'[^a-zA-Z0-9]+\'),10) from RPSG_DB.maplemonk.three60you_test_consultations ) ) where rw=1 ) where start_date < current_date() group by 1,\"Doctor Name\" order by 1 desc ), consultations AS ( select coalesce(start_date, start_date1) start_date, consultation_completed, consultation_confirmed, \'CONSULTATIONS\' AS c_marketplace, \'three60\' as data_source, consultation_leads, coalesce(a.\"Doctor Name\",b.\"Doctor Name\") \"Doctor Name\" from consultations1 a full outer join ( SELECT CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\', created_at :: DATETIME)::date AS start_date1, count(distinct id ) as consultation_leads, \"Doctor Name\" FROM ( select * from ( SELECT a.*, CASE WHEN LOWER(a.status) = \'completed\' THEN 1 ELSE 2 END AS df, RIGHT(REGEXP_REPLACE(c.phone, \'[^a-zA-Z0-9]+\'), 10) AS phone, ROW_NUMBER() OVER (PARTITION BY a.end_timestamp::date, phone ORDER BY df ASC) AS rw, \"Doctor Name\" FROM rpsg_db.maplemonk.pg_three60you_appointment a LEFT JOIN rpsg_db.maplemonk.pg_three60you_customer c ON LOWER(c.id) = LOWER(a.customer_id) left join rpsg_db.maplemonk.drname_consultations d on a.DOCTORID = d.DOCTORID WHERE RIGHT(REGEXP_REPLACE(c.phone, \'[^a-zA-Z0-9]+\'), 10) NOT IN ( SELECT DISTINCT RIGHT(REGEXP_REPLACE(phone, \'[^a-zA-Z0-9]+\'), 10) FROM RPSG_DB.maplemonk.three60you_test_consultations ) ) where rw=1 ) where start_date1 < current_date() group by 1,\"Doctor Name\" ) b on a.start_date = b.start_date1 AND lower(a.\"Doctor Name\") = lower(b.\"Doctor Name\") ) SELECT DISTINCT coalesce(FI.Date, RS.return_date, IM.Invoice_Date, c.start_date) AS date, coalesce(FI.\"Doctor Name\", RS.\"Doctor Name\", IM.\"Doctor Name\", c.\"Doctor Name\") AS \"Doctor Name\", consultation_completed, consultation_confirmed, consultation_leads, Return_Quantity, Return_Value, Total_Sales_Ex_Tax, wo_rr_TOTAL_RETURN_AMOUNT_EXCL_TAX, total_consultations, Net_Orders, Cancelled_Orders, Delivered_Orders, Delivered_Revenue, Realised_Revenue FROM orders FI FULL OUTER JOIN returnsales RS ON RS.return_date = FI.Date AND RS.\"Doctor Name\" = FI.\"Doctor Name\" FULL OUTER JOIN invoicedatemetrics IM ON IM.Invoice_Date = coalesce(FI.Date, RS.return_date) AND IM.\"Doctor Name\" =coalesce(FI.\"Doctor Name\" ,RS.\"Doctor Name\") FULL OUTER JOIN consultations c ON c.start_date = coalesce(FI.Date, RS.return_date, IM.Invoice_Date) AND C.\"Doctor Name\" = coalesce(FI.\"Doctor Name\", RS.\"Doctor Name\", IM.\"Doctor Name\") WHERE coalesce(FI.\"Doctor Name\", RS.\"Doctor Name\", IM.\"Doctor Name\", c.\"Doctor Name\") IS NOT NULL;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from RPSG_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            